/*
 * A250036  Numbers n such that m = floor(n/4) is coprime to n and, if
 *          nonzero, m is also a term of the sequence.
 * https://oeis.org/A250036
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) is the n‑th smallest positive integer n0 such that letting
 *            m = floor(n0/4) the following hold: 1. gcd(m, n0) = 1 2. if m >
 *            0, then m also belongs to the sequence. The sequence is
 *            generated by checking integers in increasing order and storing
 *            those that satisfy the conditions
 * Range:     u8 n <= 37, u16 n <= 1403, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   gcd
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include "../utils/gcd.h"

static seq_t *seq_vals = NULL;          /* sequence values (ascending) */
static size_t seq_len  = 0;             /* current length of seq_vals   */
static size_t seq_cap  = 0;             /* current capacity of seq_vals */

static uint8_t *present = NULL;         /* present[x] == 1 if x is in the sequence */
static size_t present_cap = 0;          /* capacity of present array */

static seq_t last_checked = 0;          /* last integer examined (for sequential search) */

/* Ensure seq_vals has capacity at least 'need'.  */
static void ensure_seq_cap(size_t need)
{
    if (need <= seq_cap) return;
    size_t new_cap = seq_cap ? seq_cap : 4;
    while (new_cap < need) new_cap <<= 1;
    seq_vals = (seq_t *)realloc(seq_vals, new_cap * sizeof(seq_t));
    seq_cap = new_cap;
}

/* Ensure present array has capacity at least 'need'.  */
static void ensure_present_cap(size_t need)
{
    if (need <= present_cap) return;
    size_t old_cap = present_cap;
    size_t new_cap = present_cap ? present_cap : 4;
    while (new_cap < need) new_cap <<= 1;
    uint8_t *tmp = (uint8_t *)realloc(present, new_cap);
    present = tmp;
    /* Initialize new portion to 0 */
    if (new_cap > old_cap)
        memset(present + old_cap, 0, new_cap - old_cap);
    present_cap = new_cap;
}

/* Return the n-th term of sequence A250036 (n >= 1).  */
seq_t a(idx_t n)
{
    if (n == (idx_t)0) return (seq_t)0;   /* off‑by‑one not used in tests */

    /* Extend the sequence until we have at least n terms */
    while (seq_len < n)
    {
        seq_t candidate = last_checked + 1;
        seq_t m = candidate / (seq_t)4;   /* floor division */

        bool ok = true;

        /* Coprimality test */
        if (gcd(candidate, m) != (seq_t)1) ok = false;

        /* If m>0, require m to be already in the sequence */
        if (ok && m != (seq_t)0)
        {
            ensure_present_cap((size_t)m + 1);
            if (!present[(size_t)m]) ok = false;
        }

        if (ok)
        {
            /* Store candidate as the next sequence value */
            ensure_seq_cap(seq_len + 1);
            seq_vals[seq_len++] = candidate;

            ensure_present_cap((size_t)candidate + 1);
            present[(size_t)candidate] = 1;
        }

        last_checked = candidate;
    }

    return seq_vals[n - 1];
}
